typedef struct {
    int start, end, val;
} Interval;

int cmp(const void *a, const void *b) {
    Interval *ia = (Interval *)a;
    Interval *ib = (Interval *)b;
    return ia->end - ib->end;
}

int main() {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        Interval intervals[1001];
        for (int i = 0; i < n; i++) {
            scanf("%d %d %d", &intervals[i].start, &intervals[i].end, &intervals[i].val);
        }

        qsort(intervals, n, sizeof(Interval), cmp);

        // dp[i] = max satisfaction using intervals 0..i-1 (first i intervals)
        long long dp[1001];
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            // Option 1: skip interval i-1
            dp[i] = dp[i-1];

            // Option 2: take interval i-1
            // Find last j such that intervals[j-1].end <= intervals[i-1].start
            int lo = 0, hi = i - 1;
            // binary search for rightmost j in [0, i-1] where intervals[j-1].end <= intervals[i-1].start
            // We want largest j (0..i-1) such that intervals[j-1].end <= intervals[i-1].start
            // j=0 means no previous interval taken
            int p = 0;
            int left = 1, right = i - 1;
            while (left <= right) {
                int mid = (left + right) / 2;
                if (intervals[mid-1].end <= intervals[i-1].start) {
                    p = mid;
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            long long take = dp[p] + intervals[i-1].val;
            if (take > dp[i]) dp[i] = take;
        }

        printf("%lld\n", dp[n]);
