#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int start;
    int end;
    int value;
} Date;

int compare(const void *a, const void *b) {
    return ((Date*)a)->end - ((Date*)b)->end;
}

int binarySearch(Date dates[], int index) {
    int lo = 0, hi = index - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (dates[mid].end <= dates[index].start) {
            if (dates[mid + 1].end <= dates[index].start)
                lo = mid + 1;
            else
                return mid;
        } else {
            hi = mid - 1;
        }
    }
    return -1;
}

int main() {
    int n;
    while (1) {
        scanf("%d", &n);
        if (n == 0) break;

        Date dates[n];
        for (int i = 0; i < n; i++) {
            scanf("%d %d %d", &dates[i].start, &dates[i].end, &dates[i].value);
        }

        qsort(dates, n, sizeof(Date), compare);

        int dp[n];
        dp[0] = dates[0].value;

        for (int i = 1; i < n; i++) {
            int includeVal = dates[i].value;
            int last = binarySearch(dates, i);
            if (last != -1)
                includeVal += dp[last];

            dp[i] = (includeVal > dp[i-1]) ? includeVal : dp[i-1];
        }

        printf("%d\n", dp[n-1]);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int s, e, v;
} Date;

int cmpEnd(const void *a, const void *b) {
    const Date *x = (const Date *)a;
    const Date *y = (const Date *)b;
    if (x->e != y->e) return x->e - y->e;
    return x->s - y->s;
}

int findLastNonOverlapping(Date *arr, int i) {
    int lo = 0, hi = i - 1, ans = -1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (arr[mid].e <= arr[i].s) {
            ans = mid;
            lo = mid + 1;
        } else {
            hi = mid - 1;
        }
    }
    return ans;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        Date *arr = (Date *)malloc(sizeof(Date) * n);
        long long *dp = (long long *)malloc(sizeof(long long) * n);

        for (int i = 0; i < n; i++) {
            scanf("%d %d %d", &arr[i].s, &arr[i].e, &arr[i].v);
        }

        qsort(arr, n, sizeof(Date), cmpEnd);

        for (int i = 0; i < n; i++) {
            long long take = arr[i].v;
            int p = findLastNonOverlapping(arr, i);
            if (p != -1) take += dp[p];

            long long skip = (i == 0) ? 0 : dp[i - 1];
            dp[i] = (take > skip) ? take : skip;
        }

        printf("%lld\n", dp[n - 1]);

        free(arr);
        free(dp);
    }
    return 0;
}

