int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n) {
        if (n == 0) break;
        vector<Date> dates(n);
        for (int i = 0; i < n; ++i) {
            cin >> dates[i].start >> dates[i].end >> dates[i].satisfaction;
        }

        // Sort by end time
        sort(dates.begin(), dates.end(), [](const Date &a, const Date &b) {
            return a.end < b.end;
        });

        // dp[i] = max satisfaction using first i intervals (1-indexed)
        vector<int> dp(n + 1, 0);
        vector<int> endTimes(n);
        for (int i = 0; i < n; ++i) endTimes[i] = dates[i].end;

        for (int i = 1; i <= n; ++i) {
            // Option 1: skip current interval
            dp[i] = dp[i - 1];

            // Option 2: take current interval
            int start = dates[i - 1].start;
            // Binary search for last interval with end <= start
            int lo = 0, hi = i - 1, idx = -1;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;
                if (endTimes[mid] <= start) {
                    idx = mid;
                    lo = mid + 1;
                } else {
                    hi = mid - 1;
                }
            }
            int take = dates[i - 1].satisfaction + dp[idx + 1];
            dp[i] = max(dp[i], take);
        }

        cout << dp[n] << "\n";
    }

    return 0;
}

