public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;

            int n = Integer.parseInt(line);
            if (n == 0) break;

            int[] start = new int[n];
            int[] end = new int[n];
            int[] value = new int[n];

            for (int i = 0; i < n; i++) {
                StringTokenizer st = new StringTokenizer(br.readLine());
                start[i] = Integer.parseInt(st.nextToken());
                end[i] = Integer.parseInt(st.nextToken());
                value[i] = Integer.parseInt(st.nextToken());
            }

            // Sort by end time
            Integer[] idx = new Integer[n];
            for (int i = 0; i < n; i++) idx[i] = i;
            Arrays.sort(idx, (a, b) -> end[a] - end[b]);

            int[] sortedStart = new int[n];
            int[] sortedEnd = new int[n];
            int[] sortedValue = new int[n];

            for (int i = 0; i < n; i++) {
                sortedStart[i] = start[idx[i]];
                sortedEnd[i] = end[idx[i]];
                sortedValue[i] = value[idx[i]];
            }

            // dp[i] = max satisfaction using intervals from 0..i-1
            long[] dp = new long[n + 1];
            dp[0] = 0;

            for (int i = 1; i <= n; i++) {
                // Option 1: skip interval i-1
                dp[i] = dp[i - 1];

                // Option 2: take interval i-1
                // Find latest j such that sortedEnd[j] <= sortedStart[i-1]
                int lo = 0, hi = i - 1;
                int best = 0;
                while (lo < hi) {
                    int mid = (lo + hi + 1) / 2;
                    if (sortedEnd[mid - 1] <= sortedStart[i - 1]) {
                        lo = mid;
                    } else {
                        hi = mid - 1;
                    }
                }
                best = lo;

                dp[i] = Math.max(dp[i], dp[best] + sortedValue[i - 1]);
            }

            System.out.println(dp[n]);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Date implements Comparable<Date> {
        int start, end, value;

        Date(int start, int duration, int value) {
            this.start = start;
            this.end = start + duration;
            this.value = value;
        }

        public int compareTo(Date o) {
            return Integer.compare(this.end, o.end);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int t = fs.nextInt();
        while (t-- > 0) {
            int n = fs.nextInt();
            Date[] dates = new Date[n];

            for (int i = 0; i < n; i++) {
                int s = fs.nextInt();
                int d = fs.nextInt();
                int v = fs.nextInt();
                dates[i] = new Date(s, d, v);
            }

            Arrays.sort(dates);

            int[] ends = new int[n];
            for (int i = 0; i < n; i++) ends[i] = dates[i].end;

            long[] dp = new long[n + 1];
            for (int i = 1; i <= n; i++) {
                Date cur = dates[i - 1];
                int j = upperBound(ends, cur.start); // first end > start
                dp[i] = Math.max(dp[i - 1], dp[j] + cur.value);
            }

            out.append(dp[n]).append('\n');
        }

        System.out.print(out.toString());
    }

    static int upperBound(int[] arr, int target) {
        int l = 0, r = arr.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (arr[m] <= target) l = m + 1;
            else r = m;
        }
        return l;
    }
}
